      "title": "Kimi“天才少年”离职，否认加入Anthropic",
      "summary": "首页 风闻 财经 国际 军事 观出行 观金融 产经 科技 城事 滚动 观察员 视频 Kimi“天才少年”离职，否认加入Anthropic 赖家琪 （文/赖家琪 编辑/吕栋） 10月15日，曾参与Kimi核心模型研发的17岁“天才少年”陈广宇在社交媒体发文宣布，自己最近已离开月之暗面。 陈广宇在贴文中回顾，在Kimi工作",
